const $=id=>document.getElementById(id), KEY='wordsteps-grade8-mosaic-v1';
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readSaved(){try{return JSON.parse(localStorage.getItem(KEY))||{};}catch{return {};}}
let saved=readSaved(), words=Array.isArray(saved.words)&&saved.words.length?saved.words:structuredClone(SOURCE_WORDS), stats=saved.stats||{}, mode=0, index=0, deck=[], locked=false;
const titles=['לומדים ומקשיבים','כותבים באנגלית','מבינים בעברית','משלימים משפטים'];
function persist(){try{localStorage.setItem(KEY,JSON.stringify({words,stats}));}catch{$('manageStatus').textContent='לא ניתן לשמור בדפדפן. אפשר להוריד את הרשימה לשמירה.';}}
function mix(a){return [...a].sort(()=>Math.random()-.5);}
function normalize(s){return s.toLowerCase().trim().replace(/[’‘]/g,"'").replace(/\s+/g,' ');}
function speak(text){if(!('speechSynthesis' in window)){feedback('הדפדפן הזה אינו תומך בהשמעה.','wrong');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.85;const v=speechSynthesis.getVoices().find(v=>v.lang.startsWith('en'));if(v)u.voice=v;speechSynthesis.speak(u);}
function buildDeck(){const f=$('filter').value;deck=words.filter(w=>(f==='all'||f==='core'&&!w.extra||f==='extra'&&w.extra||f==='focus'&&stats[w.en]?.focus)&&(mode!==3||w.cloze?.includes('___')));index=0;render();}
function summary(){const weak=words.filter(w=>stats[w.en]?.focus);$('count').textContent=words.length;$('listCount').textContent=words.length+' מילים';$('focusCount').textContent=weak.length+' מילים';$('focusWords').innerHTML=weak.length?weak.map(w=>`<button data-focus="${escapeHTML(w.en)}" dir="ltr">${escapeHTML(w.en)}</button>`).join(''):'<p>אחרי שתתרגלו, יופיעו כאן מילים שדרשו עוד ניסיון או הצגת תשובה.</p>';$('progress').textContent=`ההתקדמות נשמרת בדפדפן הזה. נבדקו ${words.filter(w=>stats[w.en]?.checked).length} מתוך ${words.length} מילים.`;$('wordList').innerHTML=words.map((w,i)=>`<div class="word-row"><button data-speak="${i}" aria-label="שמיעת ${escapeHTML(w.en)}">◖)) ${escapeHTML(w.en)}</button><span>${escapeHTML(w.he)}</span>${w.extra?'<small>EXTRA</small>':''}</div>`).join('');}
function feedback(text,type){const el=$('feedback');if(el){el.textContent=text;el.className='feedback '+type;}}
function mark(ok){const w=deck[index];const s=stats[w.en]||{attempts:0};s.checked=true;s.attempts++;s.focus=!ok;stats[w.en]=s;persist();summary();}
function nextButton(){if(!$('continue')){$('after').innerHTML=`<button class="primary" id="continue">${index+1<deck.length?'המילה הבאה ←':'סיום הסבב ✓'}</button>`;$('continue').onclick=()=>{if(index+1<deck.length){index++;render();}else{$('stage').innerHTML=`<p class="eyebrow">כל הכבוד!</p><h2>סיימת את הסבב 🎉</h2><p>תרגלת ${deck.length} מילים. אפשר לחזור למילים לחיזוק או להתחיל שוב.</p><button id="restart" class="primary">סבב נוסף</button>`;$('restart').onclick=()=>{deck=mix(deck);index=0;render();};}};}}
function answer(value,reveal=false){if(locked)return;const w=deck[index],ok=!reveal&&(mode===2?value===w.he:normalize(value)===normalize(w.en));if(mode===1&&!reveal&&!value.trim()){feedback('כתבו תשובה ואז בדקו אותה.','wrong');return;}mark(ok);if(ok||reveal){locked=true;feedback(ok?'נכון מאוד! ✓':`התשובה: ${mode===2?w.he:w.en}`,ok?'correct':'wrong');document.querySelectorAll('.options button, #check, #reveal').forEach(b=>b.disabled=true);nextButton();}else{feedback('כמעט! נסו שוב, או הציגו את התשובה.','wrong');}}
function render(){locked=false;document.querySelectorAll('.mode').forEach((b,i)=>{b.classList.toggle('active',i===mode);b.setAttribute('aria-pressed',String(i===mode));});$('modeTitle').textContent=titles[mode];$('position').textContent=deck.length?`${index+1} מתוך ${deck.length}`:'0 מילים';$('bar').style.width=deck.length?`${100*(index+1)/deck.length}%`:'0';summary();if(!deck.length){$('stage').innerHTML=mode===3?'<div class="empty"><h2>משפטי Unit 1 יתווספו כאן</h2><p>תרגול המשפטים ייפתח לאחר הוספת דוגמאות מעמודי הספר.<br>בינתיים אפשר ללמוד, להקשיב ולתרגל כתיבה ופירושים.</p></div>':'<div class="empty"><h2>אין מילים בקבוצה הזו</h2><p>אפשר לבחור קבוצה אחרת, או להמשיך לתרגל כדי לזהות מילים לחיזוק.</p></div>';return;}const w=deck[index];let html=`${w.extra?'<span class="extra">EXTRA</span>':''}`;if(mode===0){html+=`<p class="hint">מקשיבים, אומרים בקול וזוכרים את המשמעות</p><div class="word">${escapeHTML(w.en)}</div><p class="meaning">${escapeHTML(w.he)}</p>${w.sentence?`<p dir="ltr">${escapeHTML(w.sentence)}</p><p>${escapeHTML(w.translation||'')}</p>`:''}<button id="listen">◖)) שמיעת המילה</button><div class="navbtns"><button id="prev" ${index===0?'disabled':''}>הקודם</button><button class="primary" id="next">${index+1===deck.length?'חזרה להתחלה ↻':'המילה הבאה ←'}</button></div>`;}else if(mode===1){html+=`<p class="hint">הקשיבו למילה וכתבו אותה באנגלית. התרגום הוא רמז.</p><div class="meaning">${escapeHTML(w.he)}</div><button id="listen">◖)) שמיעת המילה</button><form id="form"><label for="answer">איך כותבים את המילה?</label><input id="answer" aria-label="תשובה באנגלית" dir="ltr" autocomplete="off" autocapitalize="off" spellcheck="false"><div class="actions"><button id="check" class="primary" type="submit">בדיקת תשובה</button><button id="reveal" type="button">הצגת התשובה</button></div></form>`;}else{const choices=mix([w,...mix(words.filter(x=>x.en!==w.en&&(mode===2?x.he!==w.he:true))).slice(0,3)]);html+=mode===2?`<p class="hint">מה המשמעות של המילה בעברית?</p><div class="word">${escapeHTML(w.en)}</div><button id="listen">◖)) שמיעת המילה</button>`:`<p class="hint">איזו מילה משלימה את המשפט? בחרו תשובה אחת.</p><p class="sentence">${escapeHTML(w.cloze)}</p>`;html+=`<div class="options">${choices.map(c=>`<button data-choice="${escapeHTML(mode===2?c.he:c.en)}" ${mode===3?'dir="ltr"':''}>${escapeHTML(mode===2?c.he:c.en)}</button>`).join('')}</div><button id="reveal">הצגת התשובה</button>`;}html+='<div id="feedback" class="feedback" role="status" aria-live="polite"></div><div id="after"></div>';$('stage').innerHTML=html;if($('listen'))$('listen').onclick=()=>speak(w.en);if(mode===0){$('prev').onclick=()=>{index--;render();};$('next').onclick=()=>{index=(index+1)%deck.length;render();};}else{if($('form'))$('form').onsubmit=e=>{e.preventDefault();answer($('answer').value);};$('reveal').onclick=()=>answer('',true);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>answer(b.dataset.choice));}}
$('modes').innerHTML=titles.map((t,i)=>`<button class="mode" data-mode="${i}"><small>0${i+1}</small>${t}</button>`).join('');document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=Number(b.dataset.mode);buildDeck();});$('filter').onchange=buildDeck;$('shuffle').onclick=()=>{deck=mix(deck);index=0;render();};$('wordList').onclick=e=>{const b=e.target.closest('[data-speak]');if(b)speak(words[Number(b.dataset.speak)].en);};$('focusWords').onclick=e=>{const b=e.target.closest('[data-focus]');if(b){mode=0;$('filter').value='focus';buildDeck();index=deck.findIndex(w=>w.en===b.dataset.focus);render();$('stage').scrollIntoView({behavior:'smooth',block:'center'});}};$('reset').onclick=()=>{if(confirm('לאפס את ההתקדמות במכשיר הזה?')){stats={};persist();buildDeck();}};
$('export').onclick=()=>{const text=words.map(w=>[w.en,w.he,w.sentence||'',w.translation||'',w.cloze||'',w.extra?'EXTRA':''].join(' | ')).join('\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='word-steps-grade8.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onclick=()=>{const lines=$('wordInput').value.trim().split('\n').filter(l=>l.trim());if(!lines.length){$('manageStatus').textContent='הוסיפו רשימת מילים לפני הטעינה.';return;}const result=[];for(const line of lines){const p=(line.includes('|')?line.split('|'):line.split(/\s+-\s+/)).map(s=>s.trim());if(p.length<2||!p[0]||!p[1]){$('manageStatus').textContent='לכל מילה נדרשים מילה באנגלית ותרגום בעברית. הרשימה לא שונתה.';return;}if(result.some(w=>normalize(w.en)===normalize(p[0]))){$('manageStatus').textContent='יש מילה כפולה ברשימה: '+p[0];return;}if(p[4]&&!p[4].includes('___')){$('manageStatus').textContent='במשפט ההשלמה יש לסמן את המילה החסרה באמצעות ___.';return;}result.push({en:p[0],he:p[1],sentence:p[2]||'',translation:p[3]||'',cloze:p[4]||'',extra:p[5]?.toUpperCase()==='EXTRA'});}if(!confirm('להחליף את הרשימה הפעילה ולאפס את ההתקדמות?'))return;words=result;stats={};persist();$('filter').value='all';buildDeck();$('manageStatus').textContent=`נטענו ${words.length} מילים בהצלחה.`;};
$('restore').onclick=()=>{if(confirm('לחזור למילות Unit 1 המקוריות ולאפס את ההתקדמות?')){words=structuredClone(SOURCE_WORDS);stats={};persist();$('filter').value='all';buildDeck();$('manageStatus').textContent='הרשימה המקורית שוחזרה.';}};
buildDeck();
